//! Identifiers of subscriptions and notifications (NGSI-LD clauses 5.2.12 and 5.3.1).

uri_identifier!(
    /// The identifier of a subscription: a URI (NGSI-LD clause 5.2.12), chosen by the subscriber or generated by
    /// the broker when the subscription is created without one (clause 5.8.1.4).
    ///
    /// ```
    /// use iri_rs::iri;
    /// use ngsi_ld::subscription::SubscriptionId;
    ///
    /// let id = SubscriptionId::from(iri!("urn:ngsi-ld:Subscription:mySubscription"));
    /// assert_eq!(
    ///     id,
    ///     "urn:ngsi-ld:Subscription:mySubscription".parse::<SubscriptionId>()?
    /// );
    /// # Ok::<(), anyhow::Error>(())
    /// ```
    SubscriptionId
);

uri_identifier!(
    /// The identifier of a notification: a URI the broker generates (NGSI-LD clause 5.3.1).
    ///
    /// ```
    /// use ngsi_ld::subscription::NotificationId;
    ///
    /// let id: NotificationId = "urn:ngsi-ld:Notification:1".parse()?;
    /// assert_eq!(id.as_str(), "urn:ngsi-ld:Notification:1");
    /// # Ok::<(), anyhow::Error>(())
    /// ```
    NotificationId
);
